  "Über FaLe PDF": "About FaLe PDF",
  "FaLe PDF funktioniert komplett offline. Es gibt kein Konto, keine Uploads, keine Werbung und kein Tracking. Deine Dateien werden ausschließlich im Speicher dieses Browsers abgelegt. Alle Funktionen – auch die, für die andere Apps ein Abo verlangen – sind kostenlos.": "FaLe PDF works completely offline. There is no account, no uploads, no ads and no tracking. Your files are stored only in this browser’s storage. All features – including those other apps charge a subscription for – are free.",
