  "Notizen": "Notes",
  "# Unser Sommerfest 2026 Warum ein Sommerfest? - Team zusammenbringen - Danke sagen für ein starkes Jahr - Neue Kolleginnen und Kollegen kennenlernen Ablauf - 15:00 Ankommen und Begrüßung - 16:00 Spiele im Park - Boule-Turnier - Staffellauf - 18:00 Grillen - 20:00 Musik > Hier an die Wetter-Alternative erinnern. Budget - Essen und Getränke: 1.200 € - Musik: 400 € - Deko: 150 € Nächste Schritte - Termin bestätigen - Helferliste aufstellen - Einladung verschicken": "# Our Summer Party 2026\nWhy a summer party?\n- Bring the team together\n- Say thanks for a strong year\n- Get to know new colleagues\nSchedule\n- 3 pm Arrival and welcome\n- 4 pm Games in the park\n  - Boules tournament\n  - Relay race\n- 6 pm Barbecue\n- 8 pm Music\n> Remember to mention the bad-weather plan.\nBudget\n- Food and drinks: €1,200\n- Music: €400\n- Decorations: €150\nNext steps\n- Confirm the date\n- Draw up a list of helpers\n- Send the invitation",
  "Fragen?": "Questions?",
