  "So geht’s": "How it works",
  "Eine Zeile ohne Zeichen davor wird zur Folie, Zeilen mit „-“ werden Stichpunkte (eingerückt = Unterpunkt). „#“ am Anfang setzt den Titel, „>“ wird zur Sprechernotiz. Oder lade ein Word-Dokument, eine Text- oder Markdown-Datei.": "A line without a leading character becomes a slide, lines starting with “-” become bullet points (indented = sub-point). “#” at the start sets the title, “>” becomes a speaker note. Or load a Word document, a text or Markdown file.",
