  "Die Spracherkennung stellt dein Browser bzw. Betriebssystem bereit. Je nach Gerät wird die Sprache dafür an dessen Anbieter (z. B. Google oder Apple) übertragen – FaLe selbst speichert und sendet nichts.": "Speech recognition is provided by your browser or operating system. Depending on the device, your voice may be sent to its provider (e.g. Google or Apple) – FaLe itself stores and sends nothing.",
  "Sprachbefehle: „Punkt“, „Komma“, „Fragezeichen“, „neue Zeile“, „neuer Absatz“.": "Dictation currently recognizes German. Voice commands: “Punkt” (period), “Komma” (comma), “Fragezeichen” (question mark), “neue Zeile” (new line), “neuer Absatz” (new paragraph).",
