  "Kopf gerade und frontal, Gesicht mittig": "Head straight and facing forward, face centered",
  "Gleichmäßiges Licht – keine Schatten im Gesicht oder auf dem Hintergrund": "Even light – no shadows on the face or the background",
  "Einfarbiger, heller Hintergrund ohne Muster": "Plain, light background without patterns",
