  "Scharf, natürliche Farben, keine Retusche am Gesicht": "Sharp, natural colors, no retouching of the face",
  "Passbild und Bewerbungsfoto zuschneiden": "Crop passport and job photos",
  "Passbild selbst machen": "Make your own passport photo",
  "Foto aufnehmen oder wählen, mit der Schablone ausrichten und als Einzelbild oder Druckbogen 10 × 15 cm speichern – für den Fotoautomaten in der Drogerie. {0}": "Take or choose a photo, align it with the guide and save it as a single image or a 10 × 15 cm print sheet – for photo print kiosks. {0}",
  "Kamera starten": "Start camera",
  "Für deutsche Personalausweise und Reisepässe verlangen die Behörden seit Mai 2025 in der Regel ein digital übermitteltes Foto (Fotostudio oder Automat im Bürgeramt). Ausgedruckte Fotos werden u. a. noch für Visa, Führerschein-Anträge oder Mitgliedsausweise genutzt – frag im Zweifel vorher nach.": "For German ID cards and passports, the authorities have generally required a digitally transmitted photo since May 2025 (photo studio or kiosk at the citizens’ office). Printed photos are still used for visas, driving licence applications or membership cards, among others – if in doubt, ask first.",
  "Foto wird geladen …": "Loading photo …",
