  "Prüfen": "Check",
  "Ziehen verschiebt, mit zwei Fingern zoomen und drehen. Oben den Scheitel zwischen die oberen Linien, das Kinn zwischen die unteren, die Augen in den grünen Bereich.": "Drag to move, zoom and rotate with two fingers. Put the top of the head between the upper lines, the chin between the lower ones and the eyes in the green area.",
  "Hintergrund aufhellen": "Brighten background",
  "– für einfarbige Hintergründe: tippe auf den Hintergrund neben dem Kopf. Er wird durch Hellgrau (#E8E8E8) ersetzt. Bei unruhigen Hintergründen bitte neu fotografieren.": "– for plain backgrounds: tap the background next to the head. It will be replaced with light gray (#E8E8E8). For busy backgrounds please take a new photo.",
  "Toleranz": "Tolerance",
  "Antippen zum Füllen": "Tap to fill",
  "FaLe PDF schneidet nach den Maßen der Vorlage zu. Ob ein Foto angenommen wird, entscheidet allein die Behörde bzw. Stelle, bei der du es einreichst.": "FaLe PDF crops to the template’s dimensions. Whether a photo is accepted is decided solely by the authority or office you submit it to.",
