  "Ob ein Foto angenommen wird, entscheidet die jeweilige Behörde oder Stelle. Für deutsche Ausweise und Pässe werden seit Mai 2025 in der Regel digital übermittelte Fotos verlangt.": "Whether a photo is accepted is decided by the authority or office in question. For German ID cards and passports, digitally transmitted photos have generally been required since May 2025.",
