  "KI-Kontingent für diesen Monat aufgebraucht. FaLe PDF ist ein kleines Projekt mit festem Monatsbudget – ab dem 1. geht es weiter.": "AI quota for this month used up. FaLe PDF is a small project with a fixed monthly budget – it continues on the 1st.",
