  "Dieses Dokument enthält keinen erkennbaren Text.": "This document contains no recognizable text.",
  "Dieses Dokument enthält keinen Text (z. B. ein Scan). Die Texterkennung ist auf diesem Gerät nicht verfügbar.": "This document contains no text (e.g. a scan). Text recognition isn’t available on this device.",
  "Text wird erkannt (OCR, auf deinem Gerät) …": "Recognizing text (OCR, on your device) …",
  "Seite {0} wird erkannt (OCR) …": "Recognizing page {0} (OCR) …",
  "Text wird erkannt (OCR) …": "Recognizing text (OCR) …",
  "In diesem Dokument wurde kein Text gefunden.": "No text was found in this document.",
  "Cloud-KI verwenden?": "Use cloud AI?",
  "Die Verarbeitung beim KI-Anbieter richtet sich nach dessen Bedingungen (siehe Datenschutzerklärung).": "Processing by the AI provider is subject to its terms (see privacy policy).",
  "Für Cloud-KI-Funktionen sendet FaLe PDF": "For cloud AI features, FaLe PDF sends",
  "nur den Text, den du für die jeweilige Aufgabe auswählst": "only the text you select for the task",
  "(z. B. deine Frage und passende Ausschnitte aus dem Dokument), verschlüsselt über unseren Server an": "(e.g. your question and matching excerpts from the document), encrypted via our server to",
  ". Deine Dateien selbst werden nicht hochgeladen.": ". Your files themselves are not uploaded.",
  "Wir speichern keine Inhalte.": "We don’t store any content.",
  "Unser Server zählt nur Anfragen: mit einer zufälligen, pseudonymen Gerätekennung und einer gekürzten, verschlüsselten (gehashten) IP-Adresse zum Schutz vor Missbrauch. Diese Zähler werden nach 30 Tagen gelöscht.": "Our server only counts requests: with a random, pseudonymous device ID and a shortened, encrypted (hashed) IP address to prevent abuse. These counters are deleted after 30 days.",
  "Bitte sende keine besonders sensiblen Daten (z. B. Gesundheits-, Ausweis- oder Kontodaten), wenn du das nicht möchtest. Für private Texte gibt es – wo verfügbar – die KI „Auf dem Gerät“.": "Please don’t send particularly sensitive data (e.g. health, ID or bank details) if you don’t want to. For private texts there is – where available – the “On device” AI.",
  "Freiwillig und jederzeit widerrufbar: In den KI-Einstellungen kannst du die Cloud-KI ausschalten. Alle anderen Funktionen von FaLe PDF bleiben ohne KI nutzbar.": "Voluntary and revocable at any time: you can turn off cloud AI in the AI settings. All other FaLe PDF features remain usable without AI.",
  "Rechtsgrundlage ist deine Einwilligung (Art. 6 Abs. 1 lit. a DSGVO). Details in der": "The legal basis is your consent (Art. 6(1)(a) GDPR). Details in the",
  ". KI kann Fehler machen – prüfe wichtige Ergebnisse.": ". AI can make mistakes – check important results.",
  "Nicht jetzt": "Not now",
  "Zustimmen und fortfahren": "Agree and continue",
  "Cloud-KI ist ausgeschaltet": "Cloud AI is turned off",
