  "frei (noch {0}× heute).": "({0}× left today).",
  "Du hast heute alle {0} kostenlosen KI-Anfragen genutzt. Morgen gibt es wieder neue – alle anderen Funktionen von FaLe PDF kannst du ganz normal weiter nutzen.": "You’ve used all {0} free AI requests today. There will be new ones tomorrow – you can keep using all other FaLe PDF features as usual.",
  "Mit": "With",
  "bekommst du deutlich mehr KI-Anfragen pro Tag und unterstützt die Entwicklung.": "you get many more AI requests per day and support development.",
  "FaLe Plus ansehen": "See FaLe Plus",
  "KI-Kontingent für diesen Monat aufgebraucht": "AI quota for this month used up",
  "Alle anderen Funktionen bleiben nutzbar. Zusammenfassen und Übersetzen funktionieren – wo verfügbar – auch „Auf dem Gerät“.": "All other features remain usable. Summarizing and translating also work “On device” where available.",
  "{0} {1} öffnen": "Open {0} {1}",
  "Kopieren nicht möglich": "Copying not possible",
  "Als Dokument (.docx)": "As document (.docx)",
