  "In dieser Datei wurde kein Text gefunden.": "No text was found in this file.",
  "Wird von deinem Browser direkt auf diesem Gerät berechnet – nichts wird hochgeladen. KI kann Fehler machen; prüfe wichtige Inhalte.": "Computed by your browser directly on this device – nothing is uploaded. AI can make mistakes; check important content.",
  "Bei Online-Käufen und Verträgen außerhalb von Geschäftsräumen gilt meist eine Widerrufsfrist von 14 Tagen ab Erhalt der Ware bzw. Vertragsschluss. Ein Grund ist nicht nötig.": "In Germany, online purchases and contracts concluded away from business premises usually have a 14-day withdrawal period from receipt of the goods or conclusion of the contract. No reason is needed.",
  "Dein Unternehmen": "Your company",
  "Abholung von Dokumenten": "Collecting documents",
  "Gespeichert in deinen Dateien.{0}": "Saved to your files.{0}",
  "Im Editor öffnen": "Open in editor",
  "Ordner konnte nicht angelegt werden.": "Folder could not be created.",
  "Alle Dateien im Papierkorb werden endgültig gelöscht.": "All files in the trash will be deleted permanently.",
  "{0} Datei{1} · {2}": "{0} {0|file|files} · {2}",
  "Gelöschte Dateien erscheinen hier.": "Deleted files appear here.",
  "{0} Gruppe{1} identischer Dateien": "{0} {0|group|groups} of identical files",
  "Verglichen wird der Inhalt (SHA-256), nicht nur der Name. Löschen der Kopien spart {0}. Gelöschte Dateien landen im Papierkorb.": "The content is compared (SHA-256), not just the name. Deleting the copies saves {0}. Deleted files go to the trash.",
  "Alle Dateien auf diesem Gerät sind einzigartig. 🎉": "All files on this device are unique. 🎉",
  "{0} identische Dateien · je {1}": "{0} identical files · {1} each",
  "Zugehörige Datei (optional)": "Related file (optional)",
  "Trage Ablaufdaten, Kündigungsfristen und Zahlungstermine ein – FaLe erinnert dich rechtzeitig. Tipp: Im Menü jeder Datei gibt es „Frist hinzufügen“.": "Add expiry dates, notice periods and payment dates – FaLe reminds you in time. Tip: every file’s menu has “Add deadline”.",
  "10 Dateien erstellt ✨": "10 files created ✨",
  "100 Dateien erstellt 🚀": "100 files created 🚀",
  "Die Datei ist kein FaLe-Tresor-Backup.": "The file is not a FaLe vault backup.",
  "Dein Gerät liefert über die WebAuthn-PRF-Erweiterung einen eigenen Schlüssel – damit kann der Tresor auch ohne PIN entsperrt werden.": "Your device provides its own key via the WebAuthn PRF extension – so the vault can be unlocked without a PIN.",
  "Dein Gerät unterstützt keine Schlüsselableitung. Fingerabdruck/Gesicht dienen daher nur als bequeme Zugangssperre, solange die App geöffnet ist. Nach einem Neustart brauchst du die PIN; die Verschlüsselung selbst beruht immer auf der PIN.": "Your device doesn’t support key derivation. Fingerprint/face therefore only serve as a convenient access lock while the app is open. After a restart you need the PIN; the encryption itself is always based on the PIN.",
  "Was schützt deine Dateien?": "What protects your files?",
  "Jede Datei wird mit": "Every file is encrypted with",
  "verschlüsselt, bevor sie gespeichert wird – auch der Dateiname. Der Schlüssel entsteht aus deiner PIN mit": "before it is stored – including the file name. The key is derived from your PIN with",
  "und wird nirgends gespeichert.": "and is not stored anywhere.",
  "Entsperrt liegen Dateien nur im Arbeitsspeicher. Der Tresor sperrt sich nach {0} Minuten ohne Aktivität und sofort, wenn du die App verlässt.": "When unlocked, files are only kept in memory. The vault locks after {0} minutes without activity and immediately when you leave the app.",
  "Wer die PIN vergisst, kann die Dateien nicht mehr öffnen – auch nicht mit Hilfe von FaLe.": "Anyone who forgets the PIN can no longer open the files – not even with FaLe’s help.",
  "Dein privater Tresor": "Your private vault",
  "Für Ausweis-Scans, Verträge, Arztbriefe und alles, was niemand sehen soll – selbst wenn jemand dein entsperrtes Handy in der Hand hat. Dateien werden mit deiner PIN verschlüsselt und bleiben auf diesem Gerät.": "For ID scans, contracts, medical letters and everything nobody should see – even if someone has your unlocked phone in their hands. Files are encrypted with your PIN and stay on this device.",
  "Wenn du die PIN vergisst, sind die Dateien im Tresor verloren. Es gibt keine Hintertür und keine Wiederherstellung – auch nicht durch FaLe. Erstelle bei Bedarf ein Backup.": "If you forget the PIN, the files in the vault are lost. There is no back door and no recovery – not even by FaLe. Create a backup if needed.",
  "1 verschlüsselte Datei": "1 encrypted file",
  "{0} verschlüsselte Dateien": "{0} encrypted files",
  "Ohne PIN lassen sich die Dateien nicht entschlüsseln – das ist der Sinn des Tresors. Du kannst den Tresor nur komplett löschen und neu beginnen.": "Without the PIN the files can’t be decrypted – that’s the point of the vault. You can only delete the vault completely and start over.",
  "Tresor löschen": "Delete vault",
  "Alle Dateien im Tresor werden unwiderruflich gelöscht. Das kann nicht rückgängig gemacht werden.": "All files in the vault will be deleted permanently. This can’t be undone.",
  "{0} Dateien in den Tresor verschoben": "{0} files moved to the vault",
  "Aus Dateien": "From Files",
  "Die Dateien bleiben verschlüsselt, nur der Zugang ändert sich.": "The files stay encrypted, only the access changes.",
  "Entfernt alle Dateien im Tresor unwiderruflich.": "Removes all files in the vault permanently.",
  "Lege Dateien aus deiner Bibliothek oder direkt vom Gerät hier ab. Im Menü jeder Datei findest du auch „In den Tresor verschieben“.": "Put files from your library or straight from the device here. Every file’s menu also has “Move to vault”.",
  "Alle Dateien im Tresor werden unwiderruflich gelöscht.": "All files in the vault will be deleted permanently.",
