  "Schärfen, Schatten von Dokumentfotos entfernen, Rauschen mindern, Moiré reduzieren, Filter, zuschneiden, Größe und Format ändern – alles auf deinem Gerät. {0}": "Sharpen, remove shadows from document photos, reduce noise and moiré, filters, crop, change size and format – all on your device. {0}",
