  "Dein KI-Assistent": "Your AI assistant",
  "Stell Fragen an deine Dokumente, lass sie zusammenfassen oder übersetzen, erstelle Folien, Lernkarten und Briefe. Gesendet wird nur, was du für eine Aufgabe auswählst – nie ohne deine Zustimmung.": "Ask your documents questions, have them summarized or translated, create slides, flashcards and letters. Only what you select for a task is sent – never without your consent.",
  "Was möchtest du tun?": "What do you want to do?",
  "Mehr KI-Anfragen pro Tag – und FaLe PDF unterstützen": "More AI requests per day – and support FaLe PDF",
  "Cloud-KI an/aus, Einwilligung, Datenschutz": "Cloud AI on/off, consent, privacy",
  "KI kann Fehler machen. Prüfe wichtige Inhalte, Zahlen und Fristen – die Ergebnisse sind keine Rechts- oder Steuerberatung.": "AI can make mistakes. Check important content, numbers and deadlines – the results are not legal or tax advice.",
  "FaLe PDF bleibt kostenlos – alle Werkzeuge, ohne Wasserzeichen. Plus ist ein freiwilliges Abo für alle, die die Cloud-KI viel nutzen und die Entwicklung unterstützen möchten.": "FaLe PDF stays free – all tools, no watermarks. Plus is an optional subscription for everyone who uses cloud AI a lot and wants to support development.",
  "Bis zu 200 KI-Anfragen pro Tag": "Up to 200 AI requests per day",
  "statt einiger weniger": "instead of just a few",
  "Keine Werbevideos": "No ad videos",
  "nötig": "needed",
  "Jederzeit in Google Play kündbar": "Cancel any time in Google Play",
  "Hilft, die KI-Kosten zu tragen und FaLe PDF weiterzuentwickeln": "Helps cover the AI costs and develop FaLe PDF further",
  "Hinweis: Solange FaLe PDF ein kleines Projekt ist, gilt für die Cloud-KI ein festes Monatsbudget für alle Nutzerinnen und Nutzer – auch mit Plus kann es in seltenen Fällen bis zum Monatsende pausieren.": "Note: as long as FaLe PDF is a small project, cloud AI has a fixed monthly budget for all users – even with Plus it may pause until the end of the month in rare cases.",
