  "Wähle PDFs (oder Bilder) und eine Aktion – FaLe PDF verarbeitet alles nacheinander auf deinem Gerät.": "Choose PDFs (or images) and an action – FaLe PDF processes everything one after the other on your device.",
  "Fotografiere eine Visitenkarte – Name, Firma, Telefon, E-Mail, Web und Adresse werden erkannt. Du kannst alles prüfen und als Kontakt (.vcf) speichern oder teilen.": "Take a photo of a business card – name, company, phone, email, web and address are recognized. You can check everything and save or share it as a contact (.vcf).",
  "Lesezeichen bilden das Inhaltsverzeichnis in der Seitenleiste jedes PDF-Programms.": "Bookmarks form the table of contents in the sidebar of every PDF app.",
  "Findet eingefügte, gelöschte und geänderte Wörter – auch wenn sich der Text auf andere Seiten verschoben hat.": "Finds inserted, deleted and changed words – even if the text has moved to other pages.",
  "Ziehe den Rahmen oder die Ecken, um weiße Ränder oder Bereiche abzuschneiden.": "Drag the frame or the corners to trim white margins or areas.",
  "Füge Text und Bilder hinzu oder tippe mit „Ersetzen“ auf vorhandenen Text, um ihn zu ändern.": "Add text and images, or use “Replace” and tap existing text to change it.",
  "Schärfen, Schatten von Dokumentfotos entfernen, Rauschen mindern, Moiré reduzieren, Filter, zuschneiden, Größe und Format ändern – alles auf deinem Gerät.": "Sharpen, remove shadows from document photos, reduce noise and moiré, filters, crop, change size and format – all on your device.",
  "Legt eine unsichtbare Textebene über gescannte Seiten: Text lässt sich danach suchen, markieren und kopieren. Das Aussehen der Seiten bleibt unverändert, Seiten mit Text werden übersprungen.": "Adds an invisible text layer over scanned pages: the text can then be searched, selected and copied. The pages look the same, pages with text are skipped.",
  "Foto aufnehmen oder wählen, mit der Schablone ausrichten und als Einzelbild oder Druckbogen 10 × 15 cm speichern – für den Fotoautomaten in der Drogerie.": "Take or choose a photo, align it with the guide and save it as a single image or a 10 × 15 cm print sheet – for photo print kiosks.",
  "– dem stärksten Verfahren des PDF-Standards. Die Datei lässt sich danach nur mit dem Passwort öffnen.": "– the strongest method of the PDF standard. Afterwards the file can only be opened with the password.",
  "{0} Du erhältst eine ungeschützte Kopie – das Original bleibt unverändert.": "{0} You get an unprotected copy – the original stays unchanged.",
  "– nicht nur überdeckt. Andere Seiten bleiben unverändert.": "– not just covered. Other pages stay unchanged.",
  "Jede Seite wird zu einer Folie (.pptx) – ideal, um ein PDF zu präsentieren.": "Every page becomes a slide (.pptx) – ideal for presenting a PDF.",
  "Wandelt die PDF in ein Word-Dokument (.docx) um – direkt auf deinem Gerät.": "Converts the PDF into a Word document (.docx) – right on your device.",
