  "Kein Abo nötig, keine Werbebanner, kein Konto. Deine Dateien bleiben auf deinem Gerät – die Cloud-KI nutzt du nur, wenn du möchtest.": "No subscription needed, no ad banners, no account. Your files stay on your device – you only use cloud AI if you want to.",
  "FaLe PDF funktioniert offline. Es gibt kein Konto, keine Werbebanner und kein Tracking. Deine Dateien werden ausschließlich im Speicher dieses Geräts abgelegt. Nur wenn du die optionale Cloud-KI nutzt, wird der dafür ausgewählte Text nach deiner Zustimmung verarbeitet. Alle Funktionen – auch die, für die andere Apps ein Abo verlangen – sind kostenlos.": "FaLe PDF works offline. There is no account, no ad banners and no tracking. Your files are stored only in this device’s storage. Only if you use the optional cloud AI is the text you select for it processed, after your consent. All features – including those other apps charge a subscription for – are free.",
  "KI-Assistent": "AI assistant",
  "KI-Ergebnis": "AI result",
  "CSV-Tabelle": "CSV spreadsheet",
  "KI-Schreibhilfe …": "AI writing assistant …",
  "QR-Code": "QR code",
