  "Beim ersten Mal werden einmalig ca. {0} Sprachdaten geladen.": "The first time, about {0} of language data is downloaded once.",
  "Ohne Internetverbindung ist die Texterkennung beim ersten Mal nicht möglich – der Scan wird ohne Text gespeichert.": "Without an internet connection, text recognition isn’t possible the first time – the scan is saved without text.",
  "Die Sprache konnte gerade nicht gewechselt werden. Bitte später erneut versuchen.": "The language could not be switched right now. Please try again later.",
  "Die Vorlagen sind allgemeine Formulierungshilfen und ersetzen keine Rechtsberatung. Bitte prüfe Fristen und Angaben selbst – im Zweifel helfen Verbraucherzentrale, Mieterverein oder eine Anwältin bzw. ein Anwalt weiter. KI kann Fehler machen.": "These letters are written in German for German recipients and follow German law. They are general wording aids, not legal advice. Please check deadlines and details yourself – if in doubt, a consumer advice centre, tenants’ association or a lawyer can help. AI can make mistakes.",
