  "z. B. Max Mustermann": "e.g. Max Mustermann",
  "z. B. Klasse 9, Kunden, Team": "e.g. class 9, customers, team",
  "Kein Konto, kein Tracking. Alles, was du öffnest oder erstellst, bleibt auf diesem Gerät. Nur wenn du die optionale Cloud-KI nutzt, wird der dafür nötige Text verarbeitet – und Werbung gibt es nur freiwillig, gegen Extra-KI-Anfragen.": "No account, no tracking. Everything you open or create stays on this device. Only when you use the optional cloud AI is the required text processed – and ads only appear if you choose to watch one for extra AI requests.",
  "Alle Werkzeuge arbeiten lokal – nichts wird hochgeladen, außer du nutzt bewusst die Cloud-KI. Auch die Pro-Funktionen sind kostenlos.": "All tools work locally – nothing is uploaded unless you choose to use the cloud AI. The Pro features are free, too.",
  // ---- Teilen & Übertragen (js/share/*) ----
  "Sicher teilen (Link)": "Share securely (link)",
  "Unterschrift anfordern": "Request signature",
  "Der Dienst ist gerade nicht erreichbar. Bitte versuche es später erneut.": "The service is not reachable right now. Please try again later.",
  "Du bist offline. Teilen, Unterschriften anfordern und Übertragen brauchen eine Internetverbindung.": "You are offline. Sharing, requesting signatures and transferring need an internet connection.",
  "Teilen ist noch nicht eingerichtet – bitte versuche es später erneut.": "Sharing is not set up yet – please try again later.",
  "Die Verbindung musste erneuert werden. Bitte versuche es noch einmal.": "The connection had to be renewed. Please try again.",
  "Das hat nicht geklappt. Bitte versuche es erneut.": "That didn’t work. Please try again.",
  "Die Datei ist zu groß (max. {0} MB).": "The file is too large (max. {0} MB).",
  "Die Datei ist unvollständig angekommen. Bitte versuche es erneut.": "The file arrived incomplete. Please try again.",
  "Ende-zu-Ende-verschlüsselt": "End-to-end encrypted",
  "Die Datei wird auf deinem Gerät mit AES-256 verschlüsselt, bevor sie hochgeladen wird. Der Schlüssel steckt nur im Link (hinter dem #) und wird nie an unseren Server gesendet – wir speichern nur verschlüsselte Daten, Größe und Ablaufzeit und löschen alles automatisch. Wichtig: Wer den vollständigen Link hat, kann die Datei öffnen. Teile ihn nur mit den richtigen Personen oder setze zusätzlich ein Passwort.": "The file is encrypted with AES-256 on your device before it is uploaded. The key is only part of the link (after the #) and is never sent to our server – we only store encrypted data, size and expiry and delete everything automatically. Important: anyone who has the complete link can open the file. Only share it with the right people, or add a password.",
  "Teilen, Unterschriften anfordern und Übertragen brauchen eine Internetverbindung. Alles andere in FaLe PDF funktioniert weiter offline.": "Sharing, requesting signatures and transferring need an internet connection. Everything else in FaLe PDF keeps working offline.",
