  "Sende das Passwort auf einem anderen Weg als den Link (z. B. per Anruf oder SMS). Ohne Passwort lässt sich die Datei nicht öffnen – auch nicht von uns.": "Send the password another way than the link (e.g. by phone call or SMS). Without the password the file cannot be opened – not even by us.",
