  "Ende-zu-Ende-verschlüsselt: Der Schlüssel steht nur im Link, unser Server sieht keine Inhalte. Braucht eine Internetverbindung.": "End-to-end encrypted: the key is only in the link, our server sees no content. Needs an internet connection.",
  "Teilen, ohne die Kontrolle abzugeben": "Share without giving up control",
  "Links sind Ende-zu-Ende-verschlüsselt und laufen automatisch ab. Unser Server sieht weder Inhalt noch Dateinamen.": "Links are end-to-end encrypted and expire automatically. Our server sees neither content nor file names.",
  "Aktualisieren": "Refresh",
  "Unterschriftsanfragen": "Signature requests",
  "Diese Liste wird nur auf diesem Gerät gespeichert. Die Links enthalten den Schlüssel – gib dieses Gerät nicht unbeaufsichtigt weiter.": "This list is only stored on this device. The links contain the key – don’t leave this device unattended with others.",
  "Noch keine Links. Tippe auf „Sicher teilen“, um eine Datei verschlüsselt zu teilen.": "No links yet. Tap “Share securely” to share a file encrypted.",
