  "Ende-zu-Ende-verschlüsselt: Der Schlüssel steht nur im Link hinter dem # und wird nie an den Server gesendet. Entschlüsselt wird hier auf deinem Gerät.": "End-to-end encrypted: the key is only in the link after the # and is never sent to the server. Decryption happens here on your device.",
