  "Öffne diesen Link auf deinem anderen Handy oder Computer. Dort siehst du dann auch, wer unterschrieben hat, und kannst die fertige PDF laden.": "Open this link on your other phone or computer. There you will also see who has signed and can download the finished PDF.",
  "Wer diesen Link hat, kann die Anfrage verwalten und das Dokument lesen. Schick ihn nur an dich selbst – nicht an die Personen, die unterschreiben.": "Anyone with this link can manage the request and read the document. Only send it to yourself – not to the people who sign.",
