  "Anfrage löschen": "Delete request",
  "Der Server kennt nur den Status (offen, angesehen, unterschrieben) und die Zeitpunkte – nicht das Dokument, die Namen oder deine Nachricht.": "The server only knows the status (open, viewed, signed) and the times – not the document, the names or your message.",
  "Anfrage löschen?": "Delete request?",
  "Das verschlüsselte Dokument und alle unterschriebenen Versionen werden sofort vom Server gelöscht. Die Links funktionieren danach nicht mehr. Bereits gespeicherte PDFs in deinen Dateien bleiben erhalten.": "The encrypted document and all signed versions are deleted from the server right away. The links stop working. PDFs already saved in your files are kept.",
