  "Bitte nutze einen aktuellen Browser über HTTPS.": "Please use an up-to-date browser over HTTPS.",
  "Handy ↔ PC – direkt und verschlüsselt": "Phone ↔ PC – direct and encrypted",
  "Öffne FaLe PDF auf beiden Geräten. Ein Gerät zeigt einen QR-Code, das andere scannt ihn – fertig. Funktioniert auch zwischen App und Browser.": "Open FaLe PDF on both devices. One shows a QR code, the other scans it – done. Also works between the app and the browser.",
  "Code anzeigen": "Show code",
  "Dieses Gerät zeigt einen QR-Code und einen 6-stelligen Code.": "This device shows a QR code and a 6-digit code.",
  "Mit der Kamera dieses Geräts.": "With this device’s camera.",
  "Oder 6-stelligen Code eingeben": "Or enter the 6-digit code",
  "Verbinden": "Connect",
  "Die Übertragung läuft direkt zwischen den Geräten (WebRTC, verschlüsselt). Klappt keine direkte Verbindung, gehen die Dateien Ende-zu-Ende-verschlüsselt über unseren Server und werden nach dem Empfang, spätestens nach 1 Stunde gelöscht. Für den Verbindungsaufbau werden die öffentlichen STUN-Server von Google genutzt.": "Files go directly between the devices (WebRTC, encrypted). If no direct connection is possible, they travel end-to-end encrypted through our server and are deleted after receipt, at the latest after 1 hour. Google’s public STUN servers are used to set up the connection.",
  "Bitte gib den 6-stelligen Code ein.": "Please enter the 6-digit code.",
  "Verbindung wird vorbereitet …": "Preparing the connection …",
  "Code": "Code",
  "gültig bis {0}": "valid until {0}",
  "Warte auf das andere Gerät …": "Waiting for the other device …",
  "Scanne den QR-Code mit dem anderen Gerät (Kamera-App oder FaLe → „Geräte verbinden“ → „QR-Code scannen“) oder gib dort den Code ein.": "Scan the QR code with the other device (camera app or FaLe → “Connect devices” → “Scan QR code”) or enter the code there.",
  "Die Verbindung konnte nicht vorbereitet werden.": "The connection could not be prepared.",
