  "Über das verschlüsselte Relais (Ende-zu-Ende-verschlüsselt, max. 1 Stunde gespeichert)": "Via the encrypted relay (end-to-end encrypted, stored for max. 1 hour)",
  "Per QR-Code gekoppelt. Die Prüfnummer muss auf beiden Geräten gleich sein.": "Paired via QR code. The check number must be the same on both devices.",
  "Vergleiche die Prüfnummer auf beiden Geräten – stimmt sie überein, ist die Verbindung sicher.": "Compare the check number on both devices – if it matches, the connection is secure.",
  "Kopplung über den Code. Die Dateien sind trotzdem Ende-zu-Ende-verschlüsselt.": "Paired via code. The files are still end-to-end encrypted.",
  "Per QR-Code gekoppelt. Die Dateien sind Ende-zu-Ende-verschlüsselt.": "Paired via QR code. The files are end-to-end encrypted.",
  "Kopplung über den Code. Die Dateien sind verschlüsselt, der 6-stellige Code schützt aber schwächer als der QR-Code – für vertrauliche Dateien die Geräte per QR-Code koppeln.": "Paired via code. The files are encrypted, but the 6-digit code protects them less than the QR code – pair the devices via QR code for confidential files.",
