  "Deine Sync-Daten werden auf deinem Gerät verschlüsselt, bevor sie es verlassen. Gespeichert bei Supabase in Frankfurt (EU).": "Your sync data is encrypted on your device before it leaves it. Stored with Supabase in Frankfurt (EU).",
