  "Cloud-Speicher": "Cloud storage",
  "FaLe Sync einrichten": "Set up FaLe Sync",
  "Deine Daten werden auf diesem Gerät verschlüsselt. Den Schlüssel schützt ein Sync-Passwort, das nur du kennst – zusätzlich bekommst du einen Wiederherstellungsschlüssel zum Ausdrucken. Wir können deine Daten weder lesen noch das Passwort zurücksetzen.": "Your data is encrypted on this device. The key is protected by a sync password that only you know – plus you get a recovery key to print. We can neither read your data nor reset the password.",
  "Der Sync-Schlüssel wurde geändert": "The sync key has changed",
