  "FaLe Sync wurde auf einem anderen Gerät neu eingerichtet. Gib das neue Sync-Passwort ein.": "FaLe Sync was set up again on another device. Enter the new sync password.",
  "Gib dein Sync-Passwort ein. Danach synchronisiert dieses Gerät automatisch.": "Enter your sync password. After that this device syncs automatically.",
