  "Auf diesem Gerät gibt es einen anderen Tresor. Er wird nicht synchronisiert.": "This device has a different vault. It is not synced.",
  "Du hast die Daten auf diesem Gerät gelöscht. Deine Cloud-Daten sind unverändert – „Fortsetzen“ lädt sie wieder herunter.": "You deleted the data on this device. Your cloud data is unchanged – “Resume” downloads it again.",
