  "Ausschalten": "Turn off",
  "Alle Cloud-Daten löschen": "Delete all cloud data",
  "Löscht alles, was in der Cloud gespeichert ist, und den Sync-Schlüssel. Deine Dateien auf den Geräten bleiben.": "Deletes everything stored in the cloud and the sync key. Your files on the devices stay.",
  "Cloud-Daten löschen": "Delete cloud data",
  "Sync auf diesem Gerät ausschalten?": "Turn off sync on this device?",
  "Dieses Gerät synchronisiert nicht mehr, bis du es wieder mit deinem Sync-Passwort entsperrst. Deine Dateien bleiben hier und in der Cloud erhalten.": "This device stops syncing until you unlock it again with your sync password. Your files stay here and in the cloud.",
  "Wähle ein": "Choose a",
  ". Es verschlüsselt den Schlüssel zu deinen Daten und verlässt dein Gerät nie.": ". It encrypts the key to your data and never leaves your device.",
  "Wähle ein Sync-Passwort. Es verschlüsselt den Schlüssel zu deinen Daten und verlässt dein Gerät nie.": "Choose a sync password. It encrypts the key to your data and never leaves your device.",
  "Sync-Passwort (mindestens 10 Zeichen)": "Sync password (at least 10 characters)",
  "Sync-Passwort wiederholen": "Repeat sync password",
  "Wir können das Passwort nicht zurücksetzen. Ohne Passwort und Wiederherstellungsschlüssel sind deine Cloud-Daten verloren – deine Dateien auf den Geräten nicht.": "We cannot reset the password. Without the password and the recovery key your cloud data is lost – your files on the devices are not.",
  "Das Sync-Passwort muss mindestens 10 Zeichen lang sein.": "The sync password must be at least 10 characters long.",
  "Schlüssel werden erzeugt …": "Creating keys …",
  "FaLe Sync konnte nicht eingerichtet werden.": "FaLe Sync could not be set up.",
  "Dein Wiederherstellungsschlüssel": "Your recovery key",
  "Damit kommst du an deine Cloud-Daten, falls du dein Sync-Passwort vergisst.": "It gets you to your cloud data if you forget your sync password.",
  "Er wird nur jetzt angezeigt.": "It is shown only now.",
  "Drucke ihn aus oder bewahre ihn an einem sicheren Ort auf – nicht nur auf diesem Gerät.": "Print it or keep it in a safe place – not only on this device.",
  "Damit kommst du an deine Cloud-Daten, falls du dein Sync-Passwort vergisst. Er wird nur jetzt angezeigt. Drucke ihn aus oder bewahre ihn an einem sicheren Ort auf – nicht nur auf diesem Gerät.": "It gets you to your cloud data if you forget your sync password. It is shown only now. Print it or keep it in a safe place – not only on this device.",
  "Ich habe den Wiederherstellungsschlüssel sicher gespeichert.": "I have stored the recovery key safely.",
