  "Zur Bestätigung brauchen wir dein Sync-Passwort. Der bisherige Wiederherstellungsschlüssel funktioniert danach nicht mehr.": "To confirm, we need your sync password. The previous recovery key stops working afterwards.",
  "Alle Cloud-Daten löschen?": "Delete all cloud data?",
  "Alle verschlüsselten Daten in der Cloud und der Sync-Schlüssel werden endgültig gelöscht. Andere Geräte hören auf zu synchronisieren. Deine Dateien auf den Geräten bleiben erhalten.": "All encrypted data in the cloud and the sync key are deleted for good. Other devices stop syncing. Your files on the devices are kept.",
