  "Konto löschen?": "Delete account?",
  "Konto und alle Daten werden innerhalb von 30 Tagen vollständig gelöscht.": "Your account and all data will be completely deleted within 30 days.",
  "Deine Cloud-Daten (FaLe Sync) entfernen wir sofort, die Anmeldedaten spätestens nach 30 Tagen. Ein laufendes FaLe-Plus-Abo kündigst du bitte selbst bei Google Play.": "We remove your cloud data (FaLe Sync) immediately and the sign-in data after 30 days at the latest. Please cancel a running FaLe Plus subscription yourself in Google Play.",
  "Konto und alle Daten werden innerhalb von 30 Tagen vollständig gelöscht. Deine Cloud-Daten (FaLe Sync) entfernen wir sofort, die Anmeldedaten spätestens nach 30 Tagen. Ein laufendes FaLe-Plus-Abo kündigst du bitte selbst bei Google Play.": "Your account and all data will be completely deleted within 30 days. We remove your cloud data (FaLe Sync) immediately and the sign-in data after 30 days at the latest. Please cancel a running FaLe Plus subscription yourself in Google Play.",
