  "Nur die bereits mit deiner PIN verschlüsselten Daten": "Only the data already encrypted with your PIN",
  "FaLe PDF funktioniert offline. Du brauchst kein Konto, es gibt keine Werbebanner und kein Tracking. Deine Dateien werden im Speicher dieses Geräts abgelegt – nur wenn du das freiwillige FaLe-Konto mit FaLe Sync nutzt, zusätzlich Ende-zu-Ende-verschlüsselt in der Cloud. Nur wenn du die optionale Cloud-KI nutzt, wird der dafür ausgewählte Text nach deiner Zustimmung verarbeitet. Alle Funktionen – auch die, für die andere Apps ein Abo verlangen – sind kostenlos.": "FaLe PDF works offline. You don't need an account, there are no banner ads and no tracking. Your files are stored on this device – and only if you use the optional FaLe account with FaLe Sync, additionally end-to-end encrypted in the cloud. Only if you use the optional cloud AI, the text you select for it is processed after your consent. All features – including those other apps charge a subscription for – are free.",
