  "Antworte sachlich und nachweisbar. Berechtigte Forderungen solltest du rechtzeitig begleichen – so vermeidest du weitere Kosten. Unberechtigten Forderungen (z. B. von Inkassobüros) kannst du schriftlich widersprechen.": "Reply factually and keep proof. Pay justified claims on time – that avoids further costs. You can object in writing to unjustified claims (e.g. from debt collection agencies).",
