  "Geräte und Material für den Beruf. Bis 800 € netto (952 € brutto) im Kaufjahr voll absetzbar, darüber über die Nutzungsdauer verteilt.": "Equipment and materials for your job. Up to €800 net (€952 gross) fully deductible in the year of purchase, above that spread over the useful life.",
  "Fahrtkosten": "Travel expenses",
  "Dienstreisen, Fahrten zu Fortbildungen. Der tägliche Arbeitsweg läuft über die Entfernungspauschale – dafür sind keine Belege nötig.": "Business trips, travel to training. Your daily commute is covered by the distance allowance – no receipts needed for that.",
