  "Homeoffice": "Home office",
  "Homeoffice-Pauschale: 6 € pro Tag, höchstens 1.260 € im Jahr – dafür sind keine Belege nötig, nur die Anzahl der Tage.": "Home office allowance: €6 per day, at most €1,260 per year – no receipts needed, just the number of days.",
