  "Krankheitskosten": "Medical costs",
  "Außergewöhnliche Belastungen": "Extraordinary burdens",
  "Zuzahlungen, Brille, Zahnersatz, ärztlich verordnete Behandlungen. Wirkt erst oberhalb der zumutbaren Belastung.": "Co-payments, glasses, dentures, prescribed treatments. Only counts above the reasonable burden.",
  "Sonstige außergewöhnliche Belastungen": "Other extraordinary burdens",
  "z. B. Pflege, Beerdigung, Behinderung, Unwetterschäden.": "e.g. care, funeral, disability, storm damage.",
  "Haushaltsnahe Dienstleistungen": "Household services",
  "20 % der Arbeitskosten, höchstens 4.000 € Steuerermäßigung pro Jahr (z. B. Reinigung, Gartenpflege, Hausmeister). Nur unbar bezahlt.": "20 % of labour costs, at most €4,000 tax reduction per year (e.g. cleaning, gardening, caretaker). Only if paid by bank.",
