  "In Chrome und Edge kannst du die App auch über das Symbol „In App öffnen“ rechts in der Adressleiste starten.": "In Chrome and Edge you can also start the app with the “Open in app” icon on the right of the address bar.",
  "Jetzt installieren": "Install now",
  "Dein Browser fragt gleich noch einmal nach – klicke dort auf „Installieren“.": "Your browser will ask once more – click “Install” there.",
