  // Unterlagen anfordern (js/share/filereq.js)
  "Diese Anfrage ist beschädigt. Bitte frag nach einem neuen Link.": "This request is damaged. Please ask for a new link.",
  "Diese Datei lässt sich mit dem Schlüssel auf diesem Gerät nicht öffnen.": "This file can't be opened with the key on this device.",
  "Unterlagen anfordern": "Request documents",
  "Link senden – andere laden Dateien verschlüsselt bei dir hoch. Ohne Konto.": "Send a link – others upload files to you, encrypted. No account.",
  "Verschlüsselte Links, Unterschriften und Unterlagen anfordern, Handy ↔ PC": "Encrypted links, signature and document requests, phone ↔ PC",
  "{0} bittet dich, Unterlagen hochzuladen („{1}“). Verschlüsselt, ohne Konto:": "{0} asks you to upload documents (“{1}”). Encrypted, no account needed:",
  "Bitte lade hier deine Unterlagen hoch („{0}“). Verschlüsselt, ohne Konto:": "Please upload your documents here (“{0}”). Encrypted, no account needed:",
  "Unterlagen anfordern braucht eine HTTPS-Verbindung und einen aktuellen Browser.": "Requesting documents needs an HTTPS connection and an up-to-date browser.",
  "Dateien von anderen bekommen": "Get files from others",
  "Du bekommst einen Link. Wer ihn öffnet, kann Dateien verschlüsselt bei dir hochladen – ohne Konto, ohne App. Öffnen kannst nur du, auf diesem Gerät.": "You get a link. Whoever opens it can upload files to you, encrypted – no account, no app. Only you can open them, on this device.",
  "Wofür brauchst du die Unterlagen?": "What do you need the documents for?",
  "z. B. Unterlagen für die Steuererklärung 2026": "e.g. documents for the 2026 tax return",
  "Dein Name (sieht die andere Person)": "Your name (shown to the other person)",
  "z. B. Anna Muster oder Praxis Dr. Muster": "e.g. Anna Smith or Dr Smith's practice",
  "z. B. Bitte bis Ende des Monats hochladen. Danke!": "e.g. Please upload by the end of the month. Thanks!",
  "Welche Unterlagen? (optional)": "Which documents? (optional)",
  "Die andere Person sieht eine Checkliste und kann jede Datei einem Punkt zuordnen.": "The other person sees a checklist and can assign each file to an item.",
  "Punkt hinzufügen": "Add item",
  "Hochladen möglich für": "Uploads possible for",
  "Höchstens Dateien": "Maximum files",
  "Link zum Hochladen erstellen": "Create upload link",
  "So bleiben die Unterlagen privat": "How the documents stay private",
  "Jede Datei wird schon auf dem Gerät der anderen Person verschlüsselt – mit einem Schlüssel, den nur dieses Gerät hier hat. Unser Server sieht weder Inhalte noch Dateinamen. Wer den Link hat, kann nur hochladen, nichts herunterladen. Alles wird nach Ablauf automatisch gelöscht.": "Every file is encrypted on the other person's device – with a key only this device has. Our server sees neither contents nor file names. Whoever has the link can only upload, not download. Everything is deleted automatically when it expires.",
  "Unterlage {0}": "Document {0}",
  "z. B. Lohnsteuerbescheinigung": "e.g. payslip summary",
  "z. B. Kontoauszug": "e.g. bank statement",
  "Weitere Unterlage": "Another document",
  "Unterlage {0} entfernen": "Remove document {0}",
  "Bitte schreib kurz, wofür du die Unterlagen brauchst.": "Please say briefly what you need the documents for.",
  "Link wird erstellt …": "Creating link …",
  "Dein Link zum Hochladen ist bereit": "Your upload link is ready",
  "Hochladen möglich bis {0} · höchstens {1} Dateien": "Uploads possible until {0} · at most {1} files",
  "Die Dateien kannst du nur auf diesem Gerät in diesem Browser öffnen – hier liegt der Schlüssel. Lösch die Browserdaten nicht, bevor du alles gespeichert hast.": "You can only open the files on this device in this browser – the key is stored here. Don't clear your browser data before you've saved everything.",
  "Eingang ansehen": "View inbox",
  "Link zum Hochladen": "Upload link",
  "Diese Anfrage ist auf diesem Gerät nicht gespeichert. Die hochgeladenen Dateien lassen sich nur auf dem Gerät öffnen, auf dem du die Anfrage erstellt hast.": "This request isn't stored on this device. Uploaded files can only be opened on the device where you created the request.",
  "Unterlagen-Eingang": "Document inbox",
  "Neue Dateien annehmen": "Accept new files",
  "Wer den Link hat, kann gerade hochladen.": "Anyone with the link can upload right now.",
  "Eingegangene Dateien": "Received files",
  "Alle als ZIP": "All as ZIP",
  "Anfrage und alle Dateien löschen": "Delete request and all files",
  "Der Server kennt nur, wie viele verschlüsselte Dateien wie groß sind und wann sie kamen – nicht Namen, Inhalte, Absender oder deine Nachricht. Nach Ablauf wird alles automatisch gelöscht.": "The server only knows how many encrypted files there are, their size and when they arrived – not names, contents, senders or your message. Everything is deleted automatically when it expires.",
  "Hochladen ist wieder möglich.": "Uploads are possible again.",
  "Es können keine neuen Dateien mehr hochgeladen werden.": "No new files can be uploaded now.",
  "Alle hochgeladenen Dateien werden sofort vom Server gelöscht und der Link funktioniert nicht mehr. Dateien, die du schon gespeichert hast, bleiben erhalten.": "All uploaded files are deleted from the server immediately and the link stops working. Files you have already saved are kept.",
  "Unterlagen": "Documents",
  "„{0}“ ist jetzt in deinen Dateien.": "“{0}” is now in your files.",
