  "Noch keine Dateien. Schick den Link an die Person, von der du Unterlagen brauchst.": "No files yet. Send the link to the person you need documents from.",
  "Datei lässt sich nicht öffnen": "File can't be opened",
  "Vom Server löschen": "Delete from server",
  "„{0}“ wird sofort vom Server gelöscht.": "“{0}” will be deleted from the server immediately.",
  "Datei gelöscht.": "File deleted.",
  "Ende-zu-Ende-verschlüsselt: Jede Datei wird hier auf deinem Gerät verschlüsselt, bevor sie hochgeladen wird. Öffnen kann sie nur die Person, die dich gefragt hat – nicht wir und auch niemand sonst, der diesen Link hat.": "End-to-end encrypted: every file is encrypted here on your device before it is uploaded. Only the person who asked you can open it – not us, and nobody else who has this link.",
