  "Wähle PDFs (oder Bilder) und was mit allen passieren soll – FaLe PDF erledigt alles nacheinander auf deinem Gerät. Die Originale bleiben unverändert.": "Choose PDFs (or images) and what should happen to all of them – FaLe PDF does it one after another on your device. The originals stay unchanged.",
