  "Passwort der geschützten Dateien ({0})": "Password of the protected files ({0})",
  "Wird für alle geschützten Dateien versucht. Ohne passendes Passwort wird die Datei übersprungen – der Stapel läuft weiter.": "Tried for all protected files. Without a matching password the file is skipped – the batch carries on.",
  "automatisch, z. B. {datum} {name}": "automatic, e.g. {datum} {name}",
  "{name} = alter Name, {nr} = laufende Nummer, {datum} = heute. Leer = Name mit Zusatz wie „(komprimiert)“.": "{name} = old name, {nr} = running number, {datum} = today. Empty = name with an addition like “(komprimiert)”.",
  "Reihenfolge wie in der Liste oben. Wasserzeichen, Seitenzahlen, Komprimieren und Passwort gelten für die fertige PDF – die Seitenzahlen laufen durch.": "Order as in the list above. Watermark, page numbers, compression and password apply to the finished PDF – page numbers continue.",
