  "Einmal zahlen, kein Abo": "Pay once, no subscription",
  "Abo, jährlich kündbar": "Subscription, cancel yearly",
  "Abo, monatlich kündbar": "Subscription, cancel monthly",
  "Danke! FaLe Plus gehört jetzt dir – für immer.": "Thank you! FaLe Plus is now yours – forever.",
  "Die Zahlung ist noch in Bearbeitung. Plus wird aktiv, sobald sie bestätigt ist – dann „Käufe wiederherstellen“ antippen.": "The payment is still being processed. Plus becomes active once it’s confirmed – then tap “Restore purchases”.",
  "Kein aktiver Kauf gefunden.": "No active purchase found.",
  "Du wirst vor der Verlängerung erinnert.": "You’ll be reminded before it renews.",
  "Keine Erinnerung vor der Verlängerung.": "No reminder before it renews.",
  "Du hast schon einmal unterstützt – danke!": "You’ve already supported us once – thank you!",
