  "Das hat leider nicht geklappt.": "Sorry, that didn’t work.",
  "KI ausgeblendet – du findest den Schalter hier in den KI-Einstellungen.": "AI hidden – you’ll find the switch here in the AI settings.",
  "KI wird wieder angezeigt. Die Cloud-KI bleibt aus, bis du sie einschaltest.": "AI is shown again. Cloud AI stays off until you turn it on.",
  "Das hat leider nicht geklappt. Es wurde nichts abgebucht.": "Sorry, that didn’t work. You haven’t been charged.",
  "FaLe Plus verlängert sich bald": "FaLe Plus renews soon",
  "Am {day} wird dein Abo verlängert. Tippe hier, wenn du es behalten oder kündigen möchtest.": "Your subscription renews on {day}. Tap here to keep or cancel it.",
  "Ungespeicherte Änderungen gefunden": "Unsaved changes found",
  "{0} ungespeicherte Dokumente gefunden": "{0} unsaved documents found",
  "FaLe PDF wurde beendet, bevor diese Änderungen gespeichert wurden. Beim Wiederherstellen wird jeweils eine neue Datei angelegt – deine gespeicherte Fassung bleibt unverändert.": "FaLe PDF was closed before these changes were saved. Restoring creates a new file for each – your saved version stays unchanged.",
  "Verworfen": "Discarded",
  "„{0}“ konnte nicht wiederhergestellt werden.": "“{0}” could not be restored.",
  "{0} Dokumente wiederhergestellt – du findest sie unter „Zuletzt“.": "{0} documents restored – you’ll find them under “Recent”.",
  "KI ist ausgeblendet": "AI is hidden",
  "Wieder einblenden in den KI-Einstellungen": "Show it again in the AI settings",
  "Du hast die KI in den Einstellungen ausgeblendet. Diese Seite bleibt erreichbar – in der App erscheinen aber keine KI-Hinweise mehr.": "You hid the AI in the settings. This page stays reachable – but no AI hints appear in the app any more.",
  "Wieder einblenden": "Show again",
  "FaLe PDF bleibt kostenlos – alle Werkzeuge, ohne Wasserzeichen, ohne Konto. Plus ist freiwillig: für alle, die die Cloud-KI viel nutzen und FaLe PDF unterstützen möchten. Als Abo oder einmal bezahlt für immer.": "FaLe PDF stays free – every tool, no watermark, no account. Plus is optional: for everyone who uses the cloud AI a lot and wants to support FaLe PDF. As a subscription or paid once, forever.",
  "Auch ohne Abo:": "Also without a subscription:",
  "einmal zahlen, für immer behalten": "pay once, keep it forever",
  "So fair rechnen wir ab": "How we bill fairly",
  "Keine Probezeit, die heimlich zum Abo wird": "No trial that quietly turns into a subscription",
  "Kündigen mit einem Tipp – hier in der App": "Cancel with one tap – right here in the app",
  "Auf Wunsch eine Erinnerung drei Tage vor jeder Verlängerung": "If you like, a reminder three days before every renewal",
  "Ohne Plus fehlt dir keine einzige PDF-Funktion": "Without Plus you don’t miss a single PDF feature",
  "Abos verlängern sich automatisch und sind jederzeit über Google Play kündbar. Es gelten die Bedingungen von Google Play.": "Subscriptions renew automatically and can be cancelled any time via Google Play. Google Play’s terms apply.",
  "„Für immer“ ist ein einmaliger Kauf ohne Verlängerung.": "“Forever” is a one-time purchase that never renews.",
  "FaLe Plus gehört dir – für immer": "FaLe Plus is yours – forever",
  "Kein Abo, keine Verlängerung. Danke für deine Unterstützung!": "No subscription, no renewal. Thank you for your support!",
  "Abo verwalten oder kündigen": "Manage or cancel subscription",
  "Vor der Verlängerung erinnern": "Remind me before it renews",
  "Eine Mitteilung drei Tage, bevor das Abo verlängert wird.": "A notification three days before the subscription renews.",
  "Einfach Danke sagen": "Just say thanks",
  "Ein einmaliger Beitrag ohne Abo und ohne Gegenleistung – er hilft, FaLe PDF kostenlos und werbefrei zu halten.": "A one-time contribution with no subscription and nothing in return – it helps keep FaLe PDF free and ad-free.",
  "KI komplett ausblenden": "Hide AI completely",
  "Entfernt alle KI-Hinweise, -Karten und -Menüpunkte aus der App. Die Cloud-KI wird dabei ausgeschaltet.": "Removes every AI hint, card and menu item from the app. Cloud AI is switched off as well.",
